    public List<AccessPolicy> testGetAll() throws Throwable {
    LOGGER.info( "AccessPolicyTest:testGetAll() - Retrieving Collection of AccessPolicys:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all AccessPolicy : " );
    List<AccessPolicy> collection  = null;

    try {
        // call the static get method on the AccessPolicyService
        collection = service.getAllAccessPolicy();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            AccessPolicy currEntity  = null;
            Iterator<AccessPolicy> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getAccessPolicyId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

